(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fr"] = {"ui":{"skip":"Aller au contenu","back":"← Retour à AI-gile","lang.button":"Langue : {name}","lang.dialog":"Choisis une langue","lang.search":"Chercher une langue","lang.none":"Aucune langue ne correspond","lang.notYet":"{name} n'est pas encore traduit","theme.aria":"Changer de thème : clair, sombre ou noir","theme.toLight":"Passer au thème clair","theme.toDark":"Passer au thème sombre","theme.toBlack":"Passer au thème noir (vrai noir, doux pour les écrans OLED)","words.underline":"Souligner ces mots sur la page","words.underlineHelp":"Survole ou touche un mot en pointillés pour voir ce qu'il veut dire.","words.col.todo":"Les cartes choisies pour l'instant : l'équipe s'y met ensuite.","words.col.doing":"Une IA travaille sur cette carte en ce moment.","words.col.review":"Une IA a fini le travail ; une autre le vérifie avant que ça arrive jusqu'à toi.","words.col.verify":"On attend ton retour : essaie et dis-nous si ça marche.","words.col.team":"Tes notes ou réponses, en attente que l'équipe les prenne en charge.","words.col.done":"Terminé et accepté.","index.title":"AI-gile : ton équipe de dev IA, sur un seul tableau","index.description":"AI-gile est un tableau kanban pour les équipes de code IA. Elles travaillent pendant que tu dors ; tu reçois une petite pile de choses à trancher, tester et accepter.","hero.logoAlt":"Icône du tableau AI-gile","hero.h1.html":"Ton équipe de dev IA, sur un seul&nbsp;tableau.","hero.alpha":"🐣 Pré-alpha fermée","hero.alphaTitle":"Tôt et inachevé : merci de l'essayer !","hero.lede":"Elles construisent pendant que tu dors. Au réveil, une petite pile t'attend : quelques questions, quelques choses à tester, un ou deux diamants violets. Un clic, c'est accepté, et retour à ton café.","dl.windows":"Appli Windows","dl.browser":"L'utiliser dans le navigateur","dl.messenger":"📱 Messenger pour ton téléphone","dl.soon":"Bientôt disponible","dl.notify":"🔔 Préviens-moi à l'ouverture","dl.notifySmall":"Alpha ou bêta","hero.secondary":"De l'agile, mais l'équipe n'a jamais besoin du café de la réunion debout. (Elle fait quand même la réunion.)","pitch.h2":"AI-gile en autant de mots que tu veux","pitch.lede":"Choisis une longueur, d'un mot à 144. Chaque longueur est sa propre description, écrite pour cette taille. Fais glisser le curseur ou utilise les flèches du clavier.","pitch.rangeLabel":"Longueur en mots","pitch.dice":"🎲 une autre version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} lettre","pitch.letters.other":"{n} lettres","pitch.chars.one":"{n} caractère","pitch.chars.other":"{n} caractères","count.line.html.one":"{n} carte sur le tableau en ce moment","count.line.html.other":"{n} cartes sur le tableau en ce moment","people.humans.html.one":"👥 {n} humain","people.humans.html.other":"👥 {n} humains","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} au travail en ce moment","people.working.html.other":"⚡ {n} au travail en ce moment","pre.title":"AI-gile : quelque chose se prépare","pre.description":"Quelque chose se construit ici. Un tableau où des équipes d'IA construisent ce que tu demandes, et t'apprennent des choses en chemin. Pour l'instant, pré-alpha fermée entre amis.","pre.h1":"Quelque chose se construit ici. 🤫","pre.line":"Un tableau où des équipes d'IA construisent ce que tu demandes, et t'apprennent des choses en chemin. Pour l'instant, pré-alpha fermée entre amis.","pre.btn":"🔔 Préviens-moi à l'ouverture","pre.peek":"Derrière la vitre : le vrai tableau, en direct. Chaque carte est une barre de couleur.","pre.peekFake":"Derrière la vitre : voilà à quoi ressemble un tableau au travail.","pre.night":"🌙 Le veilleur de nuit est aux commandes · 😴 l'humain se repose","features.aria":"Ce qu'il fait","f.pile.h":"Une seule pile pour toi","f.pile.html":"<b>Pour toi</b> réunit tout ce qui t'attend, tous projets confondus : des questions, des choses à tester, des tâches que seul un humain peut faire. Ta file te dit ce qui vient ensuite et combien de temps ça prend.","f.sleep.h":"Des équipes qui travaillent pendant que tu dors","f.sleep.p":"Chaque projet a un chef et une équipe d'agents IA. Commente une carte et l'équipe se réveille, fait le travail, puis te le rend avec des étapes qu'un humain fatigué peut suivre.","f.tester.h":"Un testeur IA vérifie d'abord","f.tester.p":"Avant que quoi que ce soit n'arrive jusqu'à toi, un testeur suit les étapes dans une copie de l'appli et montre ce qu'il a vu, avec une capture d'écran. Feuillette celles qui sont passées et accepte d'un clic.","f.proof.h":"Des preuves, pas des promesses","f.proof.p":"Chaque remise montre ce qui a changé : les fichiers, le diff, les captures d'écran. Plus besoin d'ouvrir chaque appli pour savoir si c'est fini.","f.chat.h":"Discute avec tes chefs","f.chat.p":"Une colonne façon Discord : une icône par projet, des diamants violets pour ce qui a besoin de toi. Envoie une idée à un chef ; il en fait des cartes et un plan, avec un bouton ✅ Go.","f.tidy.h":"Se range tout seul","f.tidy.p":"Les cartes liées fusionnent, les titres confus sont corrigés, et un contrôle des tokens garde le code léger. Moins de choses entre lesquelles jongler, moins à penser.","f.private.h":"À toi, sur ton ordinateur","f.private.li1":"Le tableau tourne sur ta propre machine et ne répond qu'à toi.","f.private.li2":"Les messages privés entre personnes sont chiffrés de bout en bout.","f.private.li3":"Pas de compte, pas de traceurs, pas de cookies.","f.lang.h":"Dans ta langue","f.lang.p":"Plus de 120 langues, du néerlandais, du gallois et du japonais au pirate, à Yoda et au klingon, avec un retour rapide à l'anglais pour le jargon du métier.","f.service.h":"D’une idée à un vrai service","f.service.p":"Tu as construit avec l’IA quelque chose que des gens utilisent maintenant ? Marque-le comme service et le tableau t’aide à bien le faire tourner : contrôles de disponibilité, page d’état publique, incidents avec un compte rendu, changements qui demandent un Go, sauvegardes vérifiées chaque jour. L’aide t’explique chaque étape au fur et à mesure.","msgr.h2":"AI-gile Messenger : ton équipe dans ta poche","msgr.p1":"Parle à ton équipe IA sans ouvrir le tableau. Discute avec les chefs de tes projets et avec tes amis, consulte les étapes de test d'une carte et réponds-y, le tout depuis ton téléphone.","msgr.p2":"Pour l'associer, scanne un QR code sur ton tableau. C'est ta première fois ? Une sympathique discussion de démo te fait faire le tour.","msgr.when":"D'abord sur Android, puis une version web pour les téléphones et l'iPhone.","msgr.who":"Ton chef de projet","msgr.b1":"La correction du mode sombre est prête. Tu veux les étapes de test ?","msgr.b2":"Oui, avec plaisir !","msgr.b3":"1. Ouvre Réglages. 2. Choisis Sombre. Ça s'affiche bien ?","tl.aria":"Chronologie, de la première conversation à la feuille de route","tl.h2":"De la première discussion à la suite","tl.lede":"De vraies dates et heures, dans ton fuseau horaire. Après aujourd'hui, c'est le plan, sans date promise.","tl.today":"Aujourd'hui","tl.planned":"prévu","tl.doing":"en cours","tl.cards.one":"{n} carte","tl.cards.other":"{n} cartes","join.h2":"Rejoins-nous","join.lede":"AI-gile est construit par un drôle de barbu avec un AuDHD et quelques combats avec sa santé mentale, et par un grand nombre d'agents patients. Pour l'instant c'est privé, en alpha fermée entre amis. Envie d'essayer quand ça s'ouvrira ?","join.btn":"Je suis intéressé","join.small":"On t'écrira, rien d'autre","footer.tag":"AI-gile. Pas de traceurs, pas de cookies, pas de café de réunion debout.","footer.licence":"Licence professionnelle","footer.status":"État","footer.privacy":"Ce qu'on garde","footer.thanks":"Appels grâce à ChilledChat","form.sending":"Envoi…","form.failed":"Ça n'a pas marché : réessaie plus tard.","form.offline":"Impossible de joindre AI-gile : réessaie plus tard.","form.keep":"On s'en sert uniquement pour te répondre, puis on l'efface. Pas de traceurs, pas de cookies.","form.keepLink":"Ce qu'on garde","interest.title":"AI-gile : préviens-moi à l'ouverture de l'alpha","interest.description":"Laisse ton e-mail pour savoir quand l'alpha ou la bêta fermée d'AI-gile s'ouvre.","interest.h1":"🔔 Préviens-moi à l'ouverture","interest.lede":"AI-gile est en pré-alpha fermée. Laisse ton e-mail et on t'écrira une seule fois, quand il y aura une place pour toi.","interest.email":"Ton e-mail","interest.which":"Quel test ?","interest.alpha":"Alpha fermée : tôt, brut, beaucoup de changements","interest.beta":"Bêta : plus stable, plus tard","interest.both":"L'une ou l'autre, la première qui ouvre","interest.submit":"Inscris-moi sur la liste","interest.thanks":"Merci ! Tu es sur la liste.","licence.title":"AI-gile : licence professionnelle","licence.description":"Tu utilises AI-gile dans ton activité ? Demande une licence professionnelle gratuite.","licence.h1":"📜 Licence professionnelle","licence.lede":"Tu utilises AI-gile au travail ? Dis-nous qui tu es et ce que tu fais. Si ça fait du bien, la licence est gratuite.","licence.company":"Entreprise","licence.website":"Site web","licence.what":"Ce que tu fais","licence.how":"En quoi ça aide le monde","licence.email":"E-mail","licence.submit":"Envoyer la demande","licence.thanks":"Merci ! On te répondra par e-mail.","status.title":"État d'AI-gile","status.h1":"État d'AI-gile","status.quiet":"Tout est calme","status.intro":"AI-gile fonctionne-t-il en ce moment ? Cette page vérifie le site, le partage de tableaux, les appels et le téléchargement toutes les 5 minutes.","status.up":"Fonctionne (réponse en {ms} ms)","status.slow":"N'a pas répondu à la dernière vérification, nouvel essai en cours","status.down":"En panne : n'a pas répondu aux deux dernières vérifications","status.svc.web":"Site web","status.svc.web.offers":"Ce site : ce qu'est AI-gile, et le formulaire d'intérêt","status.svc.boards":"Partage de tableaux","status.svc.boards.offers":"Tableaux publics, messages entre amis et invitations","status.svc.calls":"Appels","status.svc.calls.offers":"Voix, vidéo et partage d'écran dans AI-gile","status.svc.download":"Téléchargement","status.svc.download.offers":"L'installateur Windows et les liens d'invitation","status.checking":"Vérification…","status.offline":"Impossible de joindre le service d'état pour le moment (nouvel essai en cours)","status.updated":"mis à jour {ago}","status.justNow":"à l'instant","status.min":"il y a {n} min","status.hours":"il y a {n} h","status.days":"il y a {n} j","privacy.title":"AI-gile : ce qu'on garde","privacy.h1":"Ce qu'on garde","privacy.lede":"En bref : seulement ce que tu nous envoies, et pas longtemps.","privacy.only":"Seulement ce que tu nous envoies : ce que tu tapes dans un formulaire, comme ton e-mail. Rien d'autre sur toi.","privacy.sealed":"C'est scellé pour que notre serveur ne puisse pas le lire : dans ton navigateur, avant que ça parte (sur un navigateur plus ancien, dès que ça arrive). Seul notre propre tableau peut l'ouvrir.","privacy.server":"C'est effacé du serveur dès que ça atteint notre tableau. Tout ce qui s'y trouve encore au bout de 30 jours est effacé de toute façon.","privacy.board":"On le garde sur notre tableau seulement jusqu'à ce qu'on t'ait répondu, puis on l'efface là aussi.","privacy.none":"Pas de traceurs, pas de cookies, pas d'outils d'analyse.","privacy.local":"Ta langue et ton choix entre clair et sombre restent dans ton propre navigateur. Ils ne nous sont jamais envoyés.","privacy.ask":"Tu veux que ce soit effacé plus tôt ? Réponds à notre e-mail et dis-le-nous.","live.h2":"Regardez-le se construire, en direct","live.caption":"Chaque carte est masquée : vous voyez la forme du travail, pas les mots.","live.watching.one":"en direct : {n} spectateur","live.watching.other":"en direct : {n} spectateurs","live.last.now":"Dernière carte déplacée à l'instant","live.last.min.one":"Dernière carte déplacée il y a {n} min","live.last.min.other":"Dernière carte déplacée il y a {n} min","live.last.hour.one":"Dernière carte déplacée il y a {n} heure","live.last.hour.other":"Dernière carte déplacée il y a {n} heures","live.last.day.one":"Dernière carte déplacée il y a {n} jour","live.last.day.other":"Dernière carte déplacée il y a {n} jours","live.offline":"Le tableau en direct fait une petite pause. Revenez bientôt.","live.cols":"Backlog|À faire|En cours|L'équipe vérifie|À tester par toi|Pour l'équipe|Terminé"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Délégué."]},{"n":2,"texts":["Kanban robotique.","Agents, organisés.","Idées, réalisées."]},{"n":3,"texts":["Kanban pour robots.","Tes idées deviennent fonctionnalités.","Kanban d'agents gratuit."]},{"n":5,"texts":["Un tableau piloté par des agents.","Tu écris, les agents construisent.","Gratuit, local, testé, un peu fou."]},{"n":8,"texts":["Un kanban gratuit où travaillent des agents IA.","Écris une idée. Les agents construisent. Tu acceptes.","L'agile pour un humain et plein de robots patients."]},{"n":13,"texts":["Un tableau kanban sur ton ordinateur, où des agents IA prennent les cartes en charge.","Écris une idée. Une équipe d'agents la construit. Un testeur la vérifie.","Gratuit, sans compte, sans traceurs : un tableau, des robots, et toi aux commandes."]},{"n":21,"texts":["AI-gile est un tableau kanban pour travailler avec des agents de code IA. Ils prennent les cartes ; toi, tu testes et tu acceptes.","Chaque projet reçoit un chef et une équipe d'agents IA. Commente n'importe quelle carte et l'équipe se met au travail.","Un tableau de tâches perso et gratuit, qui tourne sur ton propre ordinateur. Les ouvriers sont des robots. Celui qui dit oui, c'est toi."]},{"n":34,"texts":["Tu poses tes idées sur un tableau. Une équipe d'agents IA les transforme en fonctionnalités qui marchent, les teste et te les rend avec des étapes à essayer. Rien n'est terminé tant que tu ne l'as pas dit.","AI-gile est un tableau kanban fait maison, que Rich a construit avec beaucoup d'aide des agents qu'il gère maintenant. Il est gratuit, tourne sur ton ordinateur, et se partage entre amis, il ne se vend pas.","Imagine un tableau kanban tout simple, avec des colonnes du Backlog jusqu'à Terminé, sauf que les cartes sont prises par des agents IA. Ils donnent des nouvelles, posent des questions quand ils bloquent, et attendent toujours ton feu vert."]},{"n":55,"texts":["AI-gile est un tableau kanban dont l'équipe est faite d'agents IA. Chaque projet a un chef qui planifie le travail et des aides qui le construisent. Quand une fonctionnalité est prête, un testeur IA l'essaie et prend une capture d'écran, puis elle arrive dans ta pile. Accepte-la, ou commente et ils la retravaillent.","Tout a commencé comme la façon qu'avait une personne de suivre plein de sessions de code IA en même temps, puis c'est devenu un vrai tableau. Il tourne sur ta machine, ne demande aucun compte et n'a aucun traceur. Il est gratuit pour les amis et les curieux. Il est aussi inachevé : attends-toi à des aspérités et à quelques surprises.","Voici la version honnête. C'est toujours à toi d'avoir les idées, et toujours à toi de vérifier les résultats. Ce qu'AI-gile fait, c'est tout ce qu'il y a entre les deux : il garde les cartes en ordre, réveille le bon agent quand tu commentes, montre exactement ce qui a changé, et range tout ça dans une seule petite pile pour toi."]},{"n":89,"texts":["AI-gile est un tableau kanban gratuit que tu fais tourner sur ton propre ordinateur. Au lieu de personnes, chaque projet a une équipe d'agents IA : un chef qui transforme tes idées en cartes et en plan, et des aides qui prennent les cartes par ordre de priorité. Quand quelque chose est construit, un testeur IA suit les étapes de test et te montre ce qu'il a vu. Ensuite ça attend dans une pile appelée Pour toi. Tu l'acceptes, ou tu commentes et l'équipe retente sa chance. Rien n'arrive jamais dans Terminé sans toi.","Quelques fonctions que tu n'attends peut-être pas. Une veille de nuit garde la colonne À faire bien garnie pendant que tu dors, en choisissant des cartes qui n'ont pas besoin de ta réponse. Un compteur de tokens montre combien les agents ont consommé aujourd'hui et cette semaine, et le mode sans tokens leur dit d'arrêter de dépenser. Tu peux écrire à tes amis, et les messages privés sont chiffrés de bout en bout. Le tableau parle environ 120 langues, dont le néerlandais, le flamand, le pirate et le klingon. Rien de tout ça ne coûte un centime, et personne n'essaie de te le vendre non plus.","AI-gile est un petit projet personnel, pas une entreprise. Rich voulait s'occuper de plusieurs projets de code IA sans ouvrir chaque appli pour aller voir, alors lui et les agents ont construit un tableau pour ça, puis s'en sont servis pour construire le reste. Il est en pré-alpha fermée, ce qui veut dire qu'il fonctionne, à peu près, pour une poignée d'amis. Il n'y a ni page de tarifs, ni lettre d'information, ni plan de croissance. Si ça te semble utile, tu pourras demander à l'essayer quand il s'ouvrira un peu plus."]},{"n":144,"texts":["AI-gile est un tableau kanban pour un humain et beaucoup d'agents IA. Il tourne sur ton propre ordinateur et il est entièrement gratuit. Tu ajoutes des projets, et chaque projet reçoit un chef et une petite équipe. Tu discutes avec le chef, un peu comme sur Discord, et tu décris une idée ; le chef en fait des cartes et un plan, puis attend que tu appuies sur Go. L'équipe déroule les cartes par ordre de priorité, avec une ligne de commande toute simple pensée pour les modèles de langage. Avant que quoi que ce soit ne te revienne, un testeur IA suit les étapes dans une copie de l'appli et joint une capture d'écran. Le travail terminé arrive dans ta pile avec les fichiers modifiés et le diff. Tu l'acceptes, ou tu laisses un commentaire et l'équipe se réveille et réessaie. Toi seul peux déplacer une carte vers Terminé.","Une journée avec AI-gile, en gros. Le soir, tu laisses quelques commentaires : ce bouton est mal placé, cette liste devrait être triée, on pourrait avoir un mode sombre. Tu vas te coucher. Les agents lisent les commentaires, font les changements, les testent et te les rendent. Si À faire se vide, la veille de nuit le remplit depuis le backlog avec des cartes qui n'ont pas besoin de ta réponse. Le matin, il y a une seule petite pile : deux ou trois questions et quelques choses à essayer, chacune avec des étapes qu'une personne ensommeillée peut suivre et une capture d'écran qui prouve que ça marche. Tu cliques, tu acceptes les bonnes et tu renvoies le reste. Un compteur de tokens montre ce que tout ça a coûté, et le mode sans tokens est là pour les semaines maigres. Ensuite tu prends ton petit-déjeuner, ce que les agents ne savent pas encore faire pour toi.","D'abord, ce qu'AI-gile n'est pas. Ce n'est pas une start-up, ce n'est pas à vendre, et personne ne récolte tes données. C'est un tableau gratuit qui tourne sur ton ordinateur, sans compte, sans traceurs et sans cookies. Ce que c'est : un endroit bien rangé pour voir d'un coup tous tes projets de code IA, avec une équipe d'agents qui s'occupe des cartes et toi qui prends les décisions. Il fusionne les cartes liées, corrige les titres confus, et surveille que le code reste léger. Il parle environ 120 langues, du néerlandais et du flamand jusqu'au pirate et au klingon. Les amis peuvent s'écrire, en privé et chiffré. Il a été construit par Rich et un grand nombre d'agents patients, surtout en s'utilisant lui-même. Il est en pré-alpha fermée, donc il est un peu brut par endroits. Si ça te tente, demande gentiment et tu pourras entrer plus tôt que les autres."]}],"quips":{"1":"Un mot. Audacieux. Peut-être trop.","3":"Trois mots. Déjà plus honnête que la plupart des pages produit.","8":"Huit mots. Encore plus court qu'une réunion debout.","21":"Les longueurs sont des story points, au fait. Évidemment.","55":"Cinquante-cinq mots. Deux cartes ont été terminées pendant ta lecture.","144":"Voilà la longue. Il n'y a pas de 233. Les agents sont allés se coucher."}},"timeline":{"first-idea.name":"La première idée","first-idea.line":"La toute première conversation, avant la moindre ligne de code.","first-board.name":"Premier tableau","first-board.line":"Un tableau qui suit sa propre construction : cartes, colonnes, glisser-déposer, projets.","team-roles.name":"Équipe et rôles","team-roles.line":"Profils d'agents, modèles d'équipe, espaces et qui fait quoi.","install.name":"Installation et versions","install.line":"Un zip qu'un ami peut installer, mises à jour automatiques, canaux et retour en arrière.","usage-saver.name":"Économie d'usage","usage-saver.line":"Mesurer ce que coûtent les exécutions, garder le code léger, préserver ta limite.","friends.name":"Amis et partage","friends.line":"Messages privés, relais brouillé, invitations, rôles et projets partagés.","languages.name":"Langues","languages.line":"Chaque texte d'écran dans un fichier de langue, avec le néerlandais et le flamand en premier.","ai-tester.name":"Testeur IA","ai-tester.line":"Un testeur vérifie chaque remise d'abord et montre ce qu'il a vu.","website.name":"Le site web","website.line":"aigile.lol, la page teaser et cette chronologie.","streaming.name":"Chat et streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF et emojis.","no-ai.name":"Édition sans IA","no-ai.line":"Un tableau pour ceux qui codent sans IA, et des tableaux publics.","night-watch.name":"Veille de nuit","night-watch.line":"Un veilleur et un Scrum Master gardent les équipes sur la tâche pendant que tu dors.","p-more.name":"Tout le reste","p-more.line":"Des idées plus petites qui attendent encore leur tour.","p-android.name":"Téléphone et Android","p-android.line":"Accéder à ton tableau depuis un téléphone, puis une appli Android native.","p-release.name":"Alpha et après","p-release.line":"Alpha fermée, le site en ligne, puis la bêta.","p-languages.name":"Plus de langues","p-languages.line":"130 langues, et un mode immersion pour ceux qui apprennent.","p-engines.name":"Plus de moteurs IA","p-engines.line":"Choisis Claude, Codex, Gemini, Copilot ou Cursor pour chaque agent.","p-pro.name":"Pratiques pro","p-pro.line":"Étiquettes de risque, barrières de fusion, cartes d'incident et garde-fous.","p-self.name":"Prendre soin de toi","p-self.line":"Mode fatigué, rappels de bien-être et 4:20.","p-servers.name":"Serveurs et échelle","p-servers.line":"Réglages de serveur globaux, rôles et préparation de la croissance.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat Twitch, emojis personnalisés et vue publique en direct."},"words":{"button":"📖 Jargon du métier","h":"📖 Les mots expliqués","intro":"Les mots que tu croises dans AI-gile, en langage simple : construire, changer sans risque, faire tourner pour les gens qui s’en servent, et travailler en équipe avec l’IA.","search":"Chercher un mot…","none":"Aucun mot ne correspond.","close":"Fermer","count":{"one":"{count} mot","other":"{count} mots"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Construire"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Changer sans risque"},{"id":"run","name":"🛎️ Faire tourner un service"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Des idées et du travail pas encore planifiés. Personne n'y touche tant que ça ne passe pas dans À faire."},{"id":"sprint","g":"agile","word":"Sprint","text":"Une courte période de travail (souvent une ou deux semaines) avec un ensemble de cartes convenu à terminer.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un point rapide : ce que chaque membre de l'équipe a fait, ce qu'il fait ensuite et ce qui le bloque.","also":["standup","stand-ups","stand up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Un tableau avec des colonnes (À faire, En cours, Terminé) où les cartes passent de gauche à droite au fil du travail."},{"id":"wip","g":"agile","word":"Limite WIP","text":"Travail en cours : le nombre maximal de cartes qu'une colonne devrait contenir, pour que l'équipe termine les choses avant d'en commencer d'autres.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"La courte checklist de l’équipe sur ce que veut dire « terminé », comme testé et expliqué, avant qu’une carte te soit remise. Sa jumelle, la Definition of Ready, dit quand une carte est assez claire pour commencer.","also":["Definition of Ready","définition de terminé","définition de prêt"]},{"id":"retro","g":"agile","word":"Rétro","text":"Un regard en arrière sur la façon dont l’équipe travaille, pour se mettre d’accord sur une chose à mieux faire. Dans AI-gile, une rétro propose un changement aux façons de travailler de l’équipe, et tu dis Go ou Pas encore.","also":["rétros","rétrospective","rétrospectives","retro"]},{"id":"swarm","g":"agile","word":"Essaim","text":"Tout le monde sur le pont : chaque équipe laisse le reste pour aider sur un projet urgent jusqu’à ce qu’il soit réglé. Les autres projets attendent pendant ce temps.","also":["essaimer","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Celui qui fait avancer le travail : il repère les cartes bloquées, relance les équipes et te rappelle ce qui attend. Dans AI-gile, le Lead Scrum Master le fait sur tous les projets.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Dépôt","text":"Le dossier de code du projet et tout son historique de commits, en général aussi conservé sur GitHub.","also":["repo","dépôts","repository"]},{"id":"branch","g":"build","word":"Branche","text":"Une ligne de travail séparée dans le code, pour pouvoir faire des changements sans toucher à la version principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantané enregistré du code, avec une courte note sur ce qui a changé. Tu peux toujours revenir à l'un d'eux.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Envoyer les instantanés enregistrés (commits) de cet ordinateur vers GitHub, pour qu'ils soient sauvegardés et partagés."},{"id":"merge","g":"build","word":"Merge","text":"Réintégrer les changements d'une branche dans la version principale."},{"id":"pr","g":"build","word":"Pull request","text":"Demander que les changements d'une branche soient vérifiés et fusionnés dans la version principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Ranger le code sans changer ce qu'il fait : fichiers plus petits, noms plus clairs, moins de répétition."},{"id":"bug","g":"build","word":"Bug","text":"Quelque chose qui ne fonctionne pas comme il devrait.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revue par les pairs","text":"Une deuxième paire d’yeux : une autre IA vérifie le travail de chaque carte avant qu’il t’arrive, pour que moins d’erreurs passent.","also":["revue de code","code review","peer review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Essayer un travail terminé pour vérifier qu'il fait ce qui était demandé, avant de l'accepter.","also":["tests","tester","testé","testée","testés","testées"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Abréviation de l’anglais quality assurance, l’assurance qualité : les vérifications automatiques qui tournent avant que quoi que ce soit passe en ligne. Quand la QA est rouge, quelque chose a échoué, et rien ne passe en ligne tant que ce n’est pas corrigé.","also":["contrôle qualité","contrôles qualité","assurance qualité"]},{"id":"testpile","g":"test","word":"Pile de tests","text":"Les cartes terminées qui attendent que tu les essaies, l’une après l’autre. Accepte-en une ou renvoie-la avec une note, et la suivante arrive.","also":["piles de tests"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Déploiement","text":"Mettre une nouvelle version en ligne, par exemple sur un serveur où les gens l'utilisent."},{"id":"release","g":"change","word":"Version","text":"Un lot nommé de travail terminé qui passe en ligne d’un coup, avec de courtes notes sur ce qui a changé. 🚀 Versions rédige les notes à partir des cartes terminées.","also":["versions","release","releases"]},{"id":"rollback","g":"change","word":"Retour arrière","text":"Revenir à la dernière version qui marchait quand une nouvelle pose problème. Dans AI-gile, cela crée une checklist à partir des étapes d’annulation notées sur chaque changement.","also":["rollback","revenir en arrière","retours arrière"]},{"id":"live","g":"change","word":"En ligne","text":"La vraie version que les gens utilisent, par opposition à une copie pour faire des essais. Les développeurs disent aussi la production, ou la prod.","also":["production","prod","live"],"noTip":1},{"id":"change","g":"change","word":"Changement","text":"Un changement prévu sur quelque chose dont les gens dépendent, écrit d’abord : quoi, pourquoi, le risque, quand, et comment l’annuler. Lance-en un avec 🔀 Demander un changement.","also":["changements","demande de changement","demandes de changement"],"noTip":1},{"id":"risk","g":"change","word":"Risque","text":"Quelque chose qui pourrait mal tourner, noté selon sa probabilité et sa gravité. ⚠️ Risques les garde dans une seule liste, le score le plus haut en premier, chacun avec une date pour y revenir.","also":["risques","registre des risques"]},{"id":"chgwin","g":"change","word":"Fenêtre de changement","text":"Les moments où les changements ont le droit de passer en ligne, comme un mardi soir tranquille. En dehors d’une fenêtre, une carte de changement ne peut pas être terminée, sauf urgence.","also":["fenêtres de changement"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Un vote rapide juste avant qu’un changement passe en ligne : chaque personne qui doit valider dit Go ou No go. Ça n’avance que si tout le monde est d’accord.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Validation","text":"Attendre un oui avant que le travail commence. Une carte créée par un ami, ou un changement, attend dans ✅ Validations jusqu’à ce que tu l’acceptes ou la refuses.","also":["validations","approbation","approbations"]},{"id":"quiettime","g":"change","word":"Plage de calme","text":"Un moment, comme un stream, une démo ou la nuit, pendant lequel rien ne passe en ligne. Les équipes continuent de travailler et de tester, mais la mise en ligne attend la fin. Ailleurs, on parle de gel des changements.","also":["plages de calme","gel des changements","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Quelque chose que tu as construit et dont les gens dépendent, comme un site ou une appli, entretenu pour que ça continue de marcher. Coche « Ce projet est un service » et indique ce qu’il offre, qui l’utilise et qui est d’astreinte.","also":["services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Contrôle de disponibilité","text":"Une vérification automatique, toutes les quelques minutes, que ton service répond toujours. Si elle échoue plusieurs fois de suite, AI-gile ouvre tout seul une carte d’incident.","also":["disponibilité","uptime","contrôles de disponibilité"]},{"id":"statuspage","g":"run","word":"Page d’état","text":"Une page publique qui montre si un service fonctionne (vert, orange ou rouge) avec la dernière nouvelle, pour que les gens qui l’utilisent puissent regarder au lieu de demander.","also":["pages d’état","page de statut","status page"]},{"id":"desk","g":"run","word":"Guichet de service","text":"L'endroit où arrivent les questions et les signalements des gens qui utilisent ton service. AI-gile range chacun en demande, incident ou idée, et le signale quand il ressemble à quelque chose de déjà signalé.","also":["guichets de service","guichet","service desk","support"]},{"id":"svcrequest","g":"run","word":"Demande de service","text":"Quelqu'un qui demande quelque chose d'ordinaire, comme un nouveau compte ou un coup de main, au lieu de signaler une panne. Elle attend son tour ; un incident passe avant.","also":["demandes de service"]},{"id":"incident","g":"run","word":"Incident","text":"Quelque chose qui est cassé en ce moment même pour les gens qui l’utilisent, comme un site en panne. Une carte 🔥 incident passe devant tout le monde : le remettre en marche passe en premier.","also":["incidents"]},{"id":"major","g":"run","word":"Incident majeur","text":"Un gros incident : beaucoup de gens touchés, ou de l’argent ou des données en danger. Un bouton met toutes les équipes dessus (essaim), réveille la personne d’astreinte et demande un point d’état toutes les 30 minutes.","also":["incidents majeurs"]},{"id":"oncall","g":"run","word":"Astreinte","text":"Être celui ou celle qui répond quand quelque chose casse, même la nuit. Chaque service a un membre de l’équipe d’astreinte, réveillé en premier pour ses incidents.","also":["d’astreinte","astreintes","on-call"]},{"id":"replyby","g":"run","word":"Délai de réponse","text":"Combien de temps une carte peut attendre une première réponse, par exemple une heure pour un incident. Ensuite, elle reçoit une horloge rouge, pour que rien ne soit oublié en silence. On parle aussi d’objectif de réponse.","also":["délais de réponse","objectif de réponse","objectifs de réponse"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un court retour en arrière après un incident : ce qui s’est passé, ce qui a aidé et ce qu’il faut changer, sans accuser personne. Un incident ne peut pas être clos sans lui.","also":["post-mortems","postmortem","retour d’expérience"]},{"id":"problem","g":"run","word":"Problème","text":"La cause cachée derrière un ou plusieurs incidents. Une carte 🧩 problème regroupe les incidents qui reviennent sans cesse, pour que la cause soit trouvée et corrigée pour de bon.","also":["problèmes"],"noTip":1},{"id":"rootcause","g":"run","word":"Cause racine","text":"La vraie raison pour laquelle quelque chose a cassé, pas seulement ce que tu as vu mal tourner. Corrige la cause racine et l’incident arrête de revenir.","also":["causes racines","cause profonde"]},{"id":"workaround","g":"run","word":"Contournement","text":"Un moyen de faire tourner les choses en attendant la vraie correction, comme redémarrer quelque chose quand ça bloque. Il est noté sur la carte du problème pour que personne n’ait à le retrouver.","also":["contournements","solution de contournement","workaround"]},{"id":"knownerror","g":"run","word":"Erreur connue","text":"Un problème dont la cause est comprise et qui a un contournement, mais qui n’est pas encore corrigé. 🧩 Erreurs connues les liste, pour que tout le monde utilise le contournement au lieu de chercher à nouveau.","also":["erreurs connues"]},{"id":"runbook","g":"run","word":"Runbook","text":"Des instructions pas à pas pour régler un type de souci connu, pour que ce soit fait de la même façon, vite, à chaque fois. Après un gros incident, l’équipe peut en proposer un que tu valides.","also":["runbooks","procédure d’exploitation"]},{"id":"ci","g":"run","word":"Élément de configuration","text":"Une chose dont ton service dépend, comme un serveur, un domaine, un certificat, une clé ou un fournisseur. 🗂️ Éléments de configuration les liste par service, pour que tu voies ce qu'un incident touche et ce qu'il faut renouveler ou sauvegarder.","also":["éléments de configuration","élément de configuration","CI"]},{"id":"expiry","g":"run","word":"Date d'expiration","text":"AI-gile garde un œil sur des dates comme l'expiration d'un certificat ou d'un domaine. Dans les 30 jours avant la date, il crée une carte pour le renouveler, pour que rien ne s'arrête par surprise.","also":["dates d'expiration","expiration","suivi des expirations"]},{"id":"backup","g":"run","word":"Sauvegarde","text":"Une copie enregistrée de tes données d’avant, sur laquelle te rabattre si quelque chose est perdu ou abîmé. AI-gile fait chaque jour une sauvegarde de tes tableaux.","also":["sauvegardes","backup","backups"]},{"id":"restore","g":"run","word":"Restaurer","text":"Remettre des données à partir d’une sauvegarde. Une sauvegarde ne compte vraiment que si tu sais qu’elle peut être restaurée, alors ça vaut le coup d’essayer de temps en temps.","also":["restauration","restauré","restaurée"]},{"id":"svcreview","g":"run","word":"Bilan de service","text":"Un regard en arrière sur un mois d'un service : incidents ouverts et réglés, rapidité des réponses, disponibilité et tokens utilisés. Le Bilan mensuel le montre pour chaque service.","also":["bilans de service","bilan mensuel","bilans mensuels"]},{"id":"accessreview","g":"run","word":"Revue des accès","text":"Vérifier tous les 90 jours qui peut encore entrer : liens de partage, rôles des amis et secrets gardés. Tu gardes ou supprimes chacun, pour que les vieux accès ne traînent pas.","also":["revues des accès","revue d'accès"]},{"id":"improvements","g":"run","word":"Liste d'améliorations","text":"Tout ce que l'équipe a décidé d'améliorer, au même endroit : suggestions de rétro, actions de revue et corrections de problèmes, chacune avec son statut. Tu la trouves sous 📈 Améliorations.","also":["listes d'améliorations","améliorations"]},{"id":"tokencap","g":"run","word":"Plafond de tokens","text":"Une limite mensuelle des tokens que les agents d'un service peuvent utiliser. À 80 %, tu reçois un avertissement ; à 100 %, leur travail en arrière-plan attend le mois suivant ou que tu relèves le plafond.","also":["plafonds de tokens","plafond mensuel de tokens"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Une IA qui travaille seule sur une tâche : elle lit le code, fait des changements, lance des vérifications et fait son rapport.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"L'unité dans laquelle on compte la consommation de l'IA : en gros, quelques lettres de texte lues ou écrites. Moins tu en utilises, plus il te reste de forfait.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Une petite commande qui s'exécute toute seule à un moment précis, par ex. au démarrage d'une session IA, pour que l'équipe entende tes commentaires.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
